BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'equality_op') THEN
        CREATE TYPE realtime.equality_op AS ENUM(
          'eq', 'neq', 'lt', 'lte', 'gt', 'gte'
        );
    END IF;
END$$

do $$
    declare
      migrations text;
    begin
      if pg_catalog.to_regclass('supabase_migrations.schema_migrations') is not null then
        select coalesce(
          pg_catalog.jsonb_agg(pg_catalog.to_jsonb(sm) order by sm.version desc),
          '[]'::pg_catalog.jsonb
        )::text
        into migrations
        from supabase_migrations.schema_migrations sm;
      else
        migrations := '[]';
      end if;
      perform pg_catalog.set_config('supabase.studio_migrations', migrations, true);
    end $$

