-- see: https://stackoverflow.com/questions/7624919/check-if-a-user-defined-type-already-exists-in-postgresql/48382296#48382296
do $$ begin
    create type auth.factor_type as enum('totp', 'webauthn');
exception
    when duplicate_object then null;
end $$

DO $$
DECLARE
    anon_role text = COALESCE(current_setting('storage.anon_role', true), 'anon');
    authenticated_role text = COALESCE(current_setting('storage.authenticated_role', true), 'authenticated');
    service_role text = COALESCE(current_setting('storage.service_role', true), 'service_role');
BEGIN
    EXECUTE 'revoke all on storage.s3_multipart_uploads from ' || anon_role || ', ' || authenticated_role;
    EXECUTE 'revoke all on storage.s3_multipart_uploads_parts from ' || anon_role || ', ' || authenticated_role;
    EXECUTE 'GRANT ALL ON TABLE storage.s3_multipart_uploads TO ' || service_role;
    EXECUTE 'GRANT ALL ON TABLE storage.s3_multipart_uploads_parts TO ' || service_role;
    EXECUTE 'GRANT SELECT ON TABLE storage.s3_multipart_uploads TO ' || authenticated_role || ', ' || anon_role;
    EXECUTE 'GRANT SELECT ON TABLE storage.s3_multipart_uploads_parts TO ' || authenticated_role || ', ' || anon_role;
END$$

DO $$
DECLARE
  r RECORD;
BEGIN
FOR r IN
    SELECT pubname FROM pg_publication WHERE pubname LIKE 'realtime_messages%' or pubname LIKE 'supabase_realtime_messages%'
LOOP
    EXECUTE 'DROP PUBLICATION IF EXISTS ' || quote_ident(r.pubname) || ';' ;
END LOOP;
END $$

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'user_defined_filter') THEN
        CREATE TYPE realtime.user_defined_filter as (
          column_name text,
          op realtime.equality_op,
          value text
        );
    END IF;
END$$

create or replace function realtime.subscription_check_filters()
    returns trigger
    language plpgsql
as $$
declare
    col_names text[] = coalesce(
            array_agg(a.attname order by a.attnum),
            '{}'::text[]
        )
        from
            pg_catalog.pg_attribute a
        where
            a.attrelid = new.entity
            and a.attnum > 0
            and not a.attisdropped
            and pg_catalog.has_column_privilege(
                (new.claims ->> 'role'),
                a.attrelid,
                a.attnum,
                'SELECT'
            );
    filter realtime.user_defined_filter;
    col_type regtype;
    in_val jsonb;
    selected_col text;
begin
    for filter in select * from unnest(new.filters) loop
        if not filter.column_name = any(col_names) then
            raise exception 'invalid column for filter %', filter.column_name;
        end if;

        col_type = (
            select atttypid::regtype
            from pg_catalog.pg_attribute
            where attrelid = new.entity
                  and attname = filter.column_name
        );
        if col_type is null then
            raise exception 'failed to lookup type for column %', filter.column_name;
        end if;

        if filter.op = 'in'::realtime.equality_op then
            in_val = realtime.cast(filter.value, (col_type::text || '[]')::regtype);
            if coalesce(jsonb_array_length(in_val), 0) > 100 then
                raise exception 'too many values for `in` filter. Maximum 100';
            end if;
        elsif filter.op = 'is'::realtime.equality_op then
            -- `is` requires a keyword RHS rather than a typed literal
            if filter.value not in ('null', 'true', 'false', 'unknown') then
                raise exception 'invalid value for is filter: must be null, true, false, or unknown';
            end if;
            -- IS NULL works for any type, but IS TRUE/FALSE/UNKNOWN require a boolean
            -- operand. Reject the non-null keywords on non-boolean columns here so they
            -- don't abort apply_rls at WAL time.
            if filter.value <> 'null' and col_type <> 'boolean'::regtype then
                raise exception 'is % filter requires a boolean column, got %', filter.value, col_type::text;
            end if;
        elsif filter.op in ('like'::realtime.equality_op, 'ilike'::realtime.equality_op) then
            -- like/ilike apply the text pattern operator (~~); reject column types that
            -- have no such operator instead of failing at WAL time
            if not exists (
                select 1 from pg_catalog.pg_operator
                where oprname = '~~' and oprleft = col_type
            ) then
                raise exception 'operator % requires a text-compatible column type, got %', filter.op::text, col_type::text;
            end if;
        elsif filter.op in ('match'::realtime.equality_op, 'imatch'::realtime.equality_op) then
            -- match/imatch apply the regex operators ~ / ~*; reject column types that have
            -- no such operator (e.g. integer) instead of failing at WAL time, mirroring the
            -- like/ilike guard above.
            if not exists (
                select 1 from pg_catalog.pg_operator
                where oprname = case when filter.op = 'imatch'::realtime.equality_op then '~*' else '~' end
                  and oprleft = col_type
                  and oprright = col_type
                  and oprresult = 'boolean'::regtype
            ) then
                raise exception 'operator % requires a text-compatible column type, got %', filter.op::text, col_type::text;
            end if;
            -- validate the regex eagerly so a bad pattern is rejected here, not inside
            -- apply_rls where it would abort the WAL stream for the entity
            begin
                perform '' ~ filter.value;
            exception when others then
                raise exception 'invalid regular expression for % filter: %', filter.op::text, sqlerrm;
            end;
        else
            -- eq/neq/lt/lte/gt/gte: value must be coercable to the type
            perform realtime.cast(filter.value, col_type);
        end if;
    end loop;

    if new.selected_columns is not null then
        for selected_col in select * from unnest(new.selected_columns) loop
            if not selected_col = any(col_names) then
                raise exception 'invalid column for select %', selected_col;
            end if;
        end loop;
    end if;

    -- Apply consistent order to filters so the unique constraint can't be tricked by a
    -- different filter order. negate is part of the sort key.
    new.filters = coalesce(
        array_agg(f order by f.column_name, f.op, f.value, f.negate),
        '{}'
    ) from unnest(new.filters) f;

    new.selected_columns = (
        select array_agg(c order by c)
        from unnest(new.selected_columns) c
    );

    return new;
end;
$$

create or replace function realtime.apply_rls(wal jsonb, max_record_bytes int = 1024 * 1024)
      returns setof realtime.wal_rls
      language plpgsql
      volatile
    as $$
    declare
      -- Regclass of the table e.g. public.notes
      entity_ regclass = (quote_ident(wal ->> 'schema') || '.' || quote_ident(wal ->> 'table'))::regclass;

      -- I, U, D, T: insert, update ...
      action realtime.action = (
        case wal ->> 'action'
          when 'I' then 'INSERT'
          when 'U' then 'UPDATE'
          when 'D' then 'DELETE'
          else 'ERROR'
        end
      );

      -- Is row level security enabled for the table
      is_rls_enabled bool = relrowsecurity from pg_class where oid = entity_;

      subscriptions realtime.subscription[] = array_agg(subs)
        from
          realtime.subscription subs
        where
          subs.entity = entity_;

      -- Subscription vars
      roles regrole[] = array_agg(distinct us.claims_role)
        from
          unnest(subscriptions) us;

    working_role regrole;
    claimed_role regrole;
    claims jsonb;

    subscription_id uuid;
    subscription_has_access bool;
    visible_to_subscription_ids uuid[] = '{}';

    -- structured info for wal's columns
    columns realtime.wal_column[];
    -- previous identity values for update/delete
    old_columns realtime.wal_column[];

    error_record_exceeds_max_size boolean = octet_length(wal::text) > max_record_bytes;

    -- Primary jsonb output for record
    output jsonb;

  begin
    perform set_config('role', null, true);

    columns =
      array_agg(
        (
          x->>'name',
          x->>'type',
          realtime.cast((x->'value') #>> '{}', (x->>'type')::regtype),
          (pks ->> 'name') is not null,
          true
        )::realtime.wal_column
      )
      from
        jsonb_array_elements(wal -> 'columns') x
        left join jsonb_array_elements(wal -> 'pk') pks
          on (x ->> 'name') = (pks ->> 'name');

    old_columns =
      array_agg(
        (
          x->>'name',
          x->>'type',
          realtime.cast((x->'value') #>> '{}', (x->>'type')::regtype),
          (pks ->> 'name') is not null,
          true
        )::realtime.wal_column
      )
      from
        jsonb_array_elements(wal -> 'identity') x
        left join jsonb_array_elements(wal -> 'pk') pks
          on (x ->> 'name') = (pks ->> 'name');

    for working_role in select * from unnest(roles) loop

      -- Update `is_selectable` for columns and old_columns
      columns =
        array_agg(
          (
            c.name,
            c.type,
            c.value,
            c.is_pkey,
            pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')
          )::realtime.wal_column
        )
        from
          unnest(columns) c;

      old_columns =
        array_agg(
          (
            c.name,
            c.type,
            c.value,
            c.is_pkey,
            pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')
          )::realtime.wal_column
        )
        from
          unnest(old_columns) c;

        if action <> 'DELETE' and count(1) = 0 from unnest(columns) c where c.is_pkey then
          return next (
            jsonb_build_object(
              'schema', wal ->> 'schema',
              'table', wal ->> 'table',
              'type', action
            ),
            is_rls_enabled,
            -- subscriptions is already filtered by entity
            (select array_agg(s.subscription_id) from unnest(subscriptions) as s where claims_role = working_role),
            array['Error 400: Bad Request, no primary key']
          )::realtime.wal_rls;

        -- The claims role does not have SELECT permission to the primary key of entity
        elsif action <> 'DELETE' and sum(c.is_selectable::int) <> count(1) from unnest(columns) c where c.is_pkey then
          return next (
            jsonb_build_object(
              'schema', wal ->> 'schema',
              'table', wal ->> 'table',
              'type', action
            ),
            is_rls_enabled,
            (select array_agg(s.subscription_id) from unnest(subscriptions) as s where claims_role = working_role),
            array['Error 401: Unauthorized']
          )::realtime.wal_rls;

        else
          output = jsonb_build_object(
            'schema', wal ->> 'schema',
            'table', wal ->> 'table',
            'type', action,
            'commit_timestamp', (wal ->> 'timestamp')::text::timestamp with time zone,
            'columns', (
              select
                jsonb_agg(
                  jsonb_build_object(
                    'name', pa.attname,
                    'type', pt.typname
                  )
                  order by pa.attnum asc
                )
              from
                pg_attribute pa
                join pg_type pt
                  on pa.atttypid = pt.oid
              where
                attrelid = entity_
                and attnum > 0
                and pg_catalog.has_column_privilege(working_role, entity_, pa.attname, 'SELECT')
              )
          )
          -- Add "record" key for insert and update
          || case
            when error_record_exceeds_max_size then jsonb_build_object('record', '{}'::jsonb)
            when action in ('INSERT', 'UPDATE') then
              jsonb_build_object(
                'record',
                (select jsonb_object_agg((c).name, (c).value) from unnest(columns) c where (c).is_selectable)
              )
            else '{}'::jsonb
          end
          -- Add "old_record" key for update and delete
          || case
            when error_record_exceeds_max_size then jsonb_build_object('old_record', '{}'::jsonb)
            when action in ('UPDATE', 'DELETE') then
              jsonb_build_object(
                'old_record',
                (select jsonb_object_agg((c).name, (c).value) from unnest(old_columns) c where (c).is_selectable)
              )
            else '{}'::jsonb
          end;

          -- Create the prepared statement
          if is_rls_enabled and action <> 'DELETE' then
            if (select 1 from pg_prepared_statements where name = 'walrus_rls_stmt' limit 1) > 0 then
              deallocate walrus_rls_stmt;
            end if;
            execute realtime.build_prepared_statement_sql('walrus_rls_stmt', entity_, columns);
          end if;

          visible_to_subscription_ids = '{}';

          for subscription_id, claims in (
            select
              subs.subscription_id,
              subs.claims
            from
              unnest(subscriptions) subs
            where
              subs.entity = entity_
              and subs.claims_role = working_role
              and realtime.is_visible_through_filters(columns, subs.filters)
            ) loop

            if not is_rls_enabled or action = 'DELETE' then
              visible_to_subscription_ids = visible_to_subscription_ids || subscription_id;
            else
                -- Check if RLS allows the role to see the record
                perform
                  set_config('role', working_role::text, true),
                  set_config('request.jwt.claims', claims::text, true);

                execute 'execute walrus_rls_stmt' into subscription_has_access;

                if subscription_has_access then
                  visible_to_subscription_ids = visible_to_subscription_ids || subscription_id;
                end if;
            end if;
          end loop;

          perform set_config('role', null, true);

          return next (
            output,
            is_rls_enabled,
            visible_to_subscription_ids,
            case
              when error_record_exceeds_max_size then array['Error 413: Payload Too Large']
              else '{}'
            end
          )::realtime.wal_rls;

        end if;
    end loop;

    perform set_config('role', null, true);
  end;
  $$

DO $$
DECLARE
  grants text := current_setting('supautils.policy_grants', true);
BEGIN
  IF grants LIKE '%realtime.messages%' AND grants LIKE '%realtime.subscription%' THEN
    REVOKE supabase_realtime_admin FROM postgres;
